SourceCode.Declaration:
/// <summary>
/// approveLine's request. Action is APPROVE (FinalQty becomes the count) or RECOUNT (back to the counters).
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountApproveRequest
{
    DataAreaId dataAreaId;
    InventJournalId journalId;
    str userId;
    real lineNumber;
    str action;
    real finalQty;
    str reasonCode;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('LineNumber')]
public real parmLineNumber(real _value = lineNumber)
{
    lineNumber = _value;
    return lineNumber;
}

[DataMemberAttribute('Action')]
public str parmAction(str _value = action)
{
    action = _value;
    return action;
}

[DataMemberAttribute('FinalQty')]
public real parmFinalQty(real _value = finalQty)
{
    finalQty = _value;
    return finalQty;
}

[DataMemberAttribute('ReasonCode')]
public str parmReasonCode(str _value = reasonCode)
{
    reasonCode = _value;
    return reasonCode;
}
